/// Errors surfaced while generating rustdoc skeletons.
#[derive(Debug, Display, std::error::Error)]
pub enum RuskelError {
    /// Indicates that a snapshot profile is invalid or unavailable.
    #[error("Invalid snapshot profile: {0}")]
    SnapshotProfile(String),
    /// Indicates that an input could not be discovered as a snapshot package.
    #[error("Snapshot discovery failed for '{}': {message}", input.display())]
    SnapshotDiscovery {
        /// Input path associated with the failure.
        input: PathBuf,
        /// Actionable discovery failure.
        message: String,
    },
    /// Indicates that rustdoc generation failed for a selected package.
    #[error("Snapshot capture failed for package '{package}': {message}")]
    SnapshotCapture {
        /// Selected Cargo package.
        package: String,
        /// Underlying build failure.
        message: String,
    },
    /// Indicates that strict snapshot rendering rejected a public surface.
    #[error("Snapshot rendering failed for package '{package}': {message}")]
    SnapshotRender {
        /// Selected Cargo package.
        package: String,
        /// Underlying fidelity or formatting failure.
        message: String,
    },
    /// Indicates that snapshot persistence failed for a destination path.
    #[error("Snapshot store failed for '{}': {message}", path.display())]
    SnapshotStore {
        /// Destination path associated with the failure.
        path: PathBuf,
        /// Actionable persistence failure.
        message: String,
    },
    /// Indicates that a specified module could not be found.
    #[error("Module not found: {0}")]
    ModuleNotFound(String),
    /// Indicates a failure in reading a file, wrapping the underlying IO error.
    #[error("Failed to read file: {0}")]
    FileRead(std::io::Error),
    /// Indicates an I/O failure in a cache-owned path.
    #[error("Cache {action} failed for '{}': {source}", path.display())]
    CacheIo {
        /// Operation that failed.
        action: &'static str,
        /// Cache-owned path associated with the failure.
        path: PathBuf,
        /// Underlying filesystem error.
        #[source]
        source: std::io::Error,
    },
    /// Indicates that a cache root or entry has an invalid layout.
    #[error("Invalid Ruskel cache at '{}': {message}", path.display())]
    CacheLayout {
        /// Path that failed validation.
        path: PathBuf,
        /// Actionable validation failure.
        message: String,
    },
    /// Indicates a failure in the code generation process.
    #[error("{0}")]
    Generate(String),
    /// Indicates an item referenced by rustdoc output could not be found.
    #[error("Item not found in rustdoc index: {0}")]
    ItemNotFound(String),
    /// Indicates an error occurred while executing a Cargo command.
    #[error("Cargo error: {0}")]
    Cargo(String),
    /// Indicates an error occurred during code formatting.
    #[error("Formatting error: {0}")]
    Format(String),
    /// Indicates an error occurred during syntax highlighting.
    #[error("Highlighting error: {0}")]
    Highlight(String),
    /// The specified filter did not match any items.
    #[error("Filter '{0}' did not match any items")]
    FilterNotMatched(String),
    /// Failed to parse a Cargo.toml manifest
    #[error("Failed to parse Cargo.toml manifest: {0}")]
    ManifestParse(String),
    /// Indicates that the Cargo.toml manifest file could not be found in the
    /// current directory or any parent directories.
    #[error("Failed to find Cargo.toml in the current directory or any parent directories")]
    ManifestNotFound,
    /// Indicates an invalid version string was provided.
    #[error("Invalid version: {0}")]
    InvalidVersion(String),
    /// Indicates an invalid target specification was provided.
    #[error("Invalid target: {0}")]
    InvalidTarget(String),
    /// Indicates a dependency was not found in the registry.
    #[error("No matching package")]
    DependencyNotFound,
}

