pub struct SnapshotFeatures {/* private fields */}

impl SnapshotFeatures {
    /// Return whether Cargo enables every feature.
    pub fn all_features(&self) -> bool;

    /// Return whether Cargo enables each package's default features.
    pub fn default_features(&self) -> bool;

    /// Return the sorted selected feature list.
    pub fn features(&self) -> &[String];

    /// Validate and canonicalize one snapshot feature policy.
    pub fn new(
        default_features: bool,
        all_features: bool,
        features: Vec<String>,
    ) -> crate::Result<Self>;
}

/// Persistence behavior for one snapshot destination.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SnapshotMode {
    /// Replace the generated tree when captured bytes differ.
    Update,
    /// Compare captured bytes without changing the generated tree.
    Check,
}

/// Fully resolved capture profile for one invocation.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SnapshotProfile {/* private fields */}

impl SnapshotProfile {
    /// Return the shared Cargo feature policy.
    pub fn features(&self) -> &SnapshotFeatures;

    /// Validate a complete profile against the local Rust installation.
    pub fn new(
        toolchain: impl Into<String>,
        target: impl Into<String>,
        features: SnapshotFeatures,
    ) -> crate::Result<Self>;

    /// Resolve explicit overrides and invocation defaults as one profile.
    pub fn resolve(options: SnapshotProfileOptions) -> crate::Result<Self>;

    /// Return the selected Cargo target triple.
    pub fn target(&self) -> &str;

    /// Return the selected nightly toolchain.
    pub fn toolchain(&self) -> &str;
}

/// Optional capture profile overrides.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct SnapshotProfileOptions {/* private fields */}

impl SnapshotProfileOptions {
    /// Return the explicit feature-policy override.
    pub fn features(&self) -> Option<&SnapshotFeatures>;

    /// Create options with no explicit overrides.
    pub fn new() -> Self;

    /// Return the explicit target override.
    pub fn target(&self) -> Option<&str>;

    /// Return the explicit toolchain override.
    pub fn toolchain(&self) -> Option<&str>;

    /// Select the shared Cargo feature policy.
    pub fn with_features(self, features: SnapshotFeatures) -> Self;

    /// Select one Cargo target triple.
    pub fn with_target(self, target: impl Into<String>) -> Self;

    /// Select a nightly toolchain.
    pub fn with_toolchain(self, toolchain: impl Into<String>) -> Self;
}

/// Complete ordered result from one snapshot synchronization.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SnapshotReport {/* private fields */}

impl SnapshotReport {
    /// Return file results in display order.
    pub fn changes(&self) -> &[SnapshotChange];

    /// Return whether the destination matches the captured snapshot.
    pub fn is_current(&self) -> bool;

    /// Return skipped binary-only packages in package order.
    pub fn skipped_packages(&self) -> &[String];
}

/// Inputs and resolved profile for one in-memory capture.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SnapshotRequest {/* private fields */}

impl SnapshotRequest {
    /// Return the input paths in caller order.
    pub fn inputs(&self) -> &[PathBuf];

    /// Create a request for one or more local Cargo manifests or directories.
    pub fn new(inputs: Vec<PathBuf>, profile: SnapshotProfile) -> crate::Result<Self>;

    /// Return the resolved capture profile.
    pub fn profile(&self) -> &SnapshotProfile;
}

/// One physically resolved snapshot destination.
#[derive(Debug)]
pub struct SnapshotStore {/* private fields */}

impl SnapshotStore {
    /// Open and validate one generated destination.
    pub fn open(path: impl AsRef<Path>, mode: SnapshotMode) -> crate::Result<Self>;

    /// Compare or atomically update the destination with one captured snapshot.
    pub fn sync(&self, snapshot: &ApiSnapshot) -> crate::Result<SnapshotReport>;
}

/// Status for one nightly toolchain entry in the cache.
#[derive(Clone, Debug)]
pub struct ToolchainCacheStatus {/* private fields */}

impl ToolchainCacheStatus {
    /// Return the toolchain identity digest.
    pub fn identity(&self) -> &str;

    /// Return whether another operation currently holds the toolchain lease.
    pub fn is_locked(&self) -> bool;

    /// Return the last-use time when valid metadata exists.
    pub fn last_use(&self) -> Option<SystemTime>;

    /// Return the recognized toolchain-tree size in bytes.
    pub fn size_bytes(&self) -> u64;

    /// Return the recognized workspace entries in identity order.
    pub fn workspaces(&self) -> &[WorkspaceCacheStatus];
}

/// Status for one workspace entry in the cache.
#[derive(Clone, Debug)]
pub struct WorkspaceCacheStatus {/* private fields */}

impl WorkspaceCacheStatus {
    /// Return the workspace identity digest.
    pub fn identity(&self) -> &str;

    /// Return whether another operation currently holds the workspace lease.
    pub fn is_locked(&self) -> bool;

    /// Return the last-use time when valid metadata exists.
    pub fn last_use(&self) -> Option<SystemTime>;

    /// Return sorted package name and version labels observed in this entry.
    pub fn packages(&self) -> &[String];

    /// Return the recognized entry size in bytes.
    pub fn size_bytes(&self) -> u64;

    /// Return the canonical workspace root when display metadata exists.
    pub fn workspace_root(&self) -> Option<&Path>;
}

pub mod highlight {
    //! Syntax highlighting functionality for Rust code.

    /// Applies syntax highlighting to Rust code using the Solarized (dark) theme.
    ///
    /// # Arguments
    /// * `code` - The Rust code to highlight
    ///
    /// # Returns
    /// A string with ANSI escape codes for terminal color output
    pub fn highlight_code(code: &str) -> crate::Result<String>;
}

pub mod toolchain {
    //! Shared nightly/rustup helpers.
    //! Shared nightly and `rustup` helpers.

    /// Return the active portable dated-nightly toolchain name.
    pub fn active_dated_nightly() -> crate::Result<String>;

    /// Ensure the nightly toolchain exists and report whether the `rust-docs-json`
    /// component is installed.
    pub fn ensure_nightly_with_docs() -> crate::Result<bool>;

    /// Return the host target reported by the selected compiler.
    pub fn host_target(toolchain: &str) -> crate::Result<String>;

    /// Locate the nightly toolchain sysroot path.
    pub fn nightly_sysroot() -> crate::Result<PathBuf>;

    /// Locate a binary installed for the selected toolchain.
    pub fn toolchain_binary(toolchain: &str, binary: &str) -> crate::Result<PathBuf>;

    /// Return the SHA-256 identity of one compiler description.
    pub fn toolchain_identity(toolchain: &str) -> crate::Result<String>;
}
